// Fake in-memory tracer — no real OTel SDK, no network.
const recorded = [];
const tracer = {
  startSpan(name, opts = {}) {
    const span = {
      name,
      attributes: { ...(opts.attributes || {}) },
      events: [],
      status: 'UNSET',
      exceptions: [],
      ended: false,
      setAttributes(attrs) { Object.assign(this.attributes, attrs); return this; },
      addEvent(n, attrs) { this.events.push({ name: n, attrs }); return this; },
      recordException(err) { this.exceptions.push(String(err && err.message || err)); return this; },
      setStatus(s) { this.status = s; return this; },
      end() { this.ended = true; recorded.push(this); },
    };
    return span;
  },
};

const order = { id: 'o-42', valueCents: 18999, segment: 'enterprise' };
const rules = [
  { id: 'velocity', run: () => ({ outcome: 'pass' }) },
  { id: 'geo-mismatch', run: () => ({ outcome: 'flag' }) },
  { id: 'blocklist', run: () => { throw new Error('rules-engine timeout'); } },
];

function runFraudCheck() {
  // TODO: open a manual span 'fraud.check', set business attributes,
  // addEvent per rule, recordException + ERROR status on failure,
  // and end() the span in a finally block.
  for (const rule of rules) {
    rule.run();
  }
}

runFraudCheck();
console.log(JSON.stringify(recorded.map(s => ({ name: s.name, ended: s.ended, events: s.events.length, status: s.status }))));
